head.script:
scwin.trigger1_onclick = function(e) {
    var title = "12345";
    check = "same";
    //windowConContent.xml
    windowContainer1.createWindow("12345", null, "", null, "NOTICE2", "existWindow", "");
    windowContainer1.setWindowLabel("NOTICE2", "toolbar", title);
};
scwin.trigger2_onclick = function(e) {
    var title = "a1234567891011121314151617181920aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
    check = "large";
    //windowConContent.xml
    windowContainer1.createWindow("123456789101111111111111111111111111111111111111111111111111121314151617181920", null, "", null, "NOTICE3", "existWindow", "");
    windowContainer1.setWindowLabel("NOTICE3", "toolbar", title);
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "check", "same");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "check", "large");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    windowContainer1.createWindow("test", null, "", null, "NOTICE", "existWindow", "");
    window.check;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 08-Feb-2018
    //end unitTest
}
